import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

// The source of the newest diagram drawn; the band above the prompt acts on it.
const latest = atom({ plugin: 'mermaid-inline', key: 'latest' } as const, null)

type Diagram = { base64: string; width: number; height: number }
type Part = { kind: 'text'; text: string } | { kind: 'diagram'; source: string }

const cache = new Map<string, Diagram | null>()
const running = new Map<string, Promise<Diagram | null>>()

const FENCE = /```mermaid[^\S\n]*\n([\s\S]*?)\n[^\S\n]*```[^\S\n]*(?:\n|$)/g
const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'

function hash(text: string): string {
  let h = 0x811c9dc5

  for (let n = 0; n < text.length; n++) {
    h = Math.imul(h ^ text.charCodeAt(n), 0x01000193)
  }

  return (h >>> 0).toString(16) + text.length.toString(16)
}

function split(text: string): Part[] {
  const parts: Part[] = []
  let last = 0

  for (const match of text.matchAll(FENCE)) {
    const start = match.index ?? 0

    if (start > last) {
      parts.push({ kind: 'text', text: text.slice(last, start) })
    }

    parts.push({ kind: 'diagram', source: match[1] })
    last = start + match[0].length
  }

  if (last < text.length) {
    parts.push({ kind: 'text', text: text.slice(last) })
  }

  return parts
}

// Width and height sit at bytes 16 to 23 of a PNG: the first 32 base64 characters hold them.
function pngSize(base64: string): { width: number; height: number } | null {
  const bytes: number[] = []
  const head = base64.slice(0, 32)

  for (let n = 0; n < head.length; n += 4) {
    const a = ALPHABET.indexOf(head[n])
    const b = ALPHABET.indexOf(head[n + 1])
    const c = ALPHABET.indexOf(head[n + 2])
    const d = ALPHABET.indexOf(head[n + 3])
    bytes.push((a << 2) | (b >> 4), ((b & 15) << 4) | (c >> 2), ((c & 3) << 6) | d)
  }

  const read = (at: number) => ((bytes[at] << 24) | (bytes[at + 1] << 16) | (bytes[at + 2] << 8) | bytes[at + 3]) >>> 0
  const width = read(16)
  const height = read(20)

  return width > 0 && height > 0 ? { width, height } : null
}

async function render($: EngineInterface, source: string): Promise<Diagram | null> {
  const key = hash(source)
  const input = `/tmp/mermaid-inline-${key}.mmd`
  const output = `/tmp/mermaid-inline-${key}.png`

  await $.fs.write(input, source)

  const run = await $.process.run(
    ['mmdc', '-i', input, '-o', output, '-t', 'dark', '-b', 'transparent', '-s', String(RENDER_SCALE), '-q'],
    { timeoutMs: 60_000 },
  )

  if (run.exitCode !== 0) {
    return null
  }

  const { base64 } = await $.fs.read(output, { as: 'bytes' })
  const size = pngSize(base64)

  return size ? { base64, ...size } : null
}

async function diagramFor($: EngineInterface, source: string): Promise<Diagram | null> {
  const key = hash(source)

  if (cache.has(key)) {
    return cache.get(key) ?? null
  }

  let job = running.get(key)

  if (!job) {
    job = render($, source).catch(() => null)
    running.set(key, job)
  }

  const diagram = await job
  cache.set(key, diagram)
  running.delete(key)

  return diagram
}

// The PNG is RENDER_SCALE times its CSS size. A cell is about 9 by 18 CSS pixels; ZOOM draws it larger.
const RENDER_SCALE = 3
const ZOOM = 1.5

// One scale fits both limits, so a tall diagram shrinks and keeps its aspect ratio.
function cells(diagram: Diagram, maxColumns: number, maxRows: number): { columns: number; rows: number } {
  const naturalColumns = (diagram.width / RENDER_SCALE / 9) * ZOOM
  const naturalRows = (diagram.height / RENDER_SCALE / 18) * ZOOM
  const scale = Math.min(1, maxColumns / naturalColumns, maxRows / naturalRows)
  const columns = Math.max(1, Math.min(255, Math.round(naturalColumns * scale)))
  const rows = Math.max(1, Math.min(255, Math.round(naturalRows * scale)))

  return { columns, rows }
}

async function copyCode($: EngineInterface, source: string, surface: string) {
  const { isCopied } = await $.ui.copy({ text: source, surface: surface as never })

  $.ui.toast(isCopied ? 'Mermaid code copied' : 'Could not copy the mermaid code')
}

// The saved file is a fresh render on a white background, so it reads in any viewer. It opens at once.
async function savePng($: EngineInterface, source: string) {
  const key = hash(source)
  const home = await $.env.get('HOME')
  const input = `/tmp/mermaid-inline-${key}.mmd`
  const output = `${home}/Downloads/mermaid-${key}.png`

  await $.fs.write(input, source)

  const run = await $.process.run(
    ['mmdc', '-i', input, '-o', output, '-t', 'default', '-b', 'white', '-s', '3', '-q'],
    { timeoutMs: 60_000 },
  )

  if (run.exitCode !== 0) {
    $.ui.toast('Could not save the PNG')

    return
  }

  $.ui.toast(`Saved ${output}`)
  await $.process.run(['open', output], { timeoutMs: 10_000 })
}

export const register: Register = on => {
  // Drawing is pure, so the newest diagram is noted when the reply is stored.
  on('session.append', { door: 'response' }, async ($, e, next) => {
    const result = await next(e)

    for (const block of e.message.content) {
      if (block.type !== 'text') {
        continue
      }

      const sources = [...block.text.matchAll(FENCE)].map(match => match[1])
      const newest = sources[sources.length - 1]

      if (newest !== undefined) {
        await update($, latest, () => newest)
      }
    }

    return result
  })

  on('ui.render', { component: 'AssistantMessage' }, async ($, e, next) => {
    if (e.surface !== 'terminal' || !e.props.text.includes('```mermaid')) {
      return next(e)
    }

    const parts = split(e.props.text)

    if (!parts.some(part => part.kind === 'diagram')) {
      return next(e)
    }

    const drawn = await Promise.all(
      parts.map(async part => (part.kind === 'diagram' ? await diagramFor($, part.source) : null)),
    )

    if (drawn.every((diagram, n) => parts[n].kind === 'text' || diagram === null)) {
      return next(e)
    }

    const { Box, Image, Markdown } = $.ui.resolve(e)
    const maxColumns = Math.max(20, Math.min(200, (e.viewport?.columns ?? 100) - 4))
    const maxRows = Math.max(20, Math.min(80, (e.viewport?.rows ?? 50) - 6))

    return (
      <Box flexDirection="column">
        {parts.map((part, n) => {
          const diagram = drawn[n]

          if (part.kind === 'text') {
            return <Markdown key={`t${n}`} text={part.text} />
          }

          if (!diagram) {
            return <Markdown key={`d${n}`} text={'```mermaid\n' + part.source + '\n```'} />
          }

          const size = cells(diagram, maxColumns, maxRows)

          return (
            <Image
              key={`d${n}`}
              source={{ png: diagram.base64 }}
              columns={size.columns}
              rows={size.rows}
              alt="mermaid diagram"
            />
          )
        })}
      </Box>
    )
  })

  // The transcript draws no Buttons, so the actions sit in the band above the prompt.
// Another mod may draw there too, so this hook stacks its row over what `next` returns.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const source = await read($, latest)

    if (e.props.hasSurvey || source === null) {
      return next(e)
    }

    const below = await next(e)
    const { Box, Button, Text } = $.ui.resolve(e)

    return (
      <Box flexDirection="column">
        <Box flexDirection="row" gap={1}>
          <Text dimColor>Last mermaid diagram:</Text>
          <Button key="copy" label="Copy code" onPress={press => copyCode($, source, press.surface)} />
          <Button key="save" label="Save PNG" onPress={() => savePng($, source)} />
          <Button key="hide" label="Hide" onPress={() => update($, latest, () => null)} />
        </Box>
        {below ?? null}
      </Box>
    )
  })
}

